 /* Get the EVADC_GENERIC APP version */
ACS_APP_VERSION_t EVADC_GENERIC_GetAppVersion(void)
{
  ACS_APP_VERSION_t version;

  version.major = EVADC_GENERIC_MAJOR_VERSION;
  version.minor = EVADC_GENERIC_MINOR_VERSION;
  version.patch = EVADC_GENERIC_PATCH_VERSION;

  return version;
}

/* Init the EVADC module and its global registers */
EVADC_GENERIC_STATUS_t EVADC_GENERIC_Init(EVADC_GENERIC_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  EVADC_GENERIC_STATUS_t status = EVADC_GENERIC_STATUS_SUCCESS;

  if (!handle->app_is_initialized)
  {
    if (IfxEvadc_Adc_initModule(&handle->app_config->evadcModuleHandle, &handle->app_config->config) == IfxEvadc_Status_noError)
    {
      handle->app_config->evadcModuleHandle.evadc->GLOB.RCR.B.DRCTR = handle->app_config->globalRcrDataReductionMode;
      IfxEvadc_configureWaitForReadModeForGlobalResultRegister(handle->app_config->evadcModuleHandle.evadc, handle->app_config->globalRcrWaitForRead);
      handle->app_config->evadcModuleHandle.evadc->GLOB.RCR.B.SRGEN = handle->app_config->globalRcrEnableServiceGeneration;
      handle->app_config->evadcModuleHandle.evadc->GLOB.EVNP.B.REV0NP =  handle->app_config->globalNodePointer;

      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = EVADC_GENERIC_STATUS_FAILURE;
    }
  }

  return status;
}

/* Sets external multiplexer interface for a particular group */
void EVADC_GENERIC_SetEmuxInterfaceForGroup(EVADC_GENERIC_t *handle, IfxEvadc_EmuxInterface emuxInterface, IfxEvadc_GroupId group )
{
  IfxEvadc_setEmuxInterfaceForGroup(handle->app_config->evadcModuleHandle.evadc,emuxInterface,group);
}

